import { useRef, useMemo, useEffect } from "react";
import { useThree, useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { ShaderPass } from "three/examples/jsm/postprocessing/ShaderPass.js";
import { OutputPass } from "three/examples/jsm/postprocessing/OutputPass.js";

// Barrel distortion + vignette + chromatic aberration shader
const DistortionShader = {
    uniforms: {
        tDiffuse: { value: null },
        uDistortion: { value: 0.0 },
        uVignetteOffset: { value: 1.0 },
        uVignetteDarkness: { value: 1.2 },
        uChromaticAberration: { value: 0.002 },
        uTime: { value: 0.0 },
        uGlowIntensity: { value: 0.0 },
        uBgColor: { value: new THREE.Color("#f7f7f9") },
        uIsDark: { value: 0.0 },
    },

    vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,

    fragmentShader: /* glsl */ `
    uniform sampler2D tDiffuse;
    uniform float uDistortion;
    uniform float uVignetteOffset;
    uniform float uVignetteDarkness;
    uniform float uChromaticAberration;
    uniform float uTime;
    uniform float uGlowIntensity;
    uniform vec3 uBgColor;
    uniform float uIsDark;
    varying vec2 vUv;

    vec2 barrelDistortion(vec2 uv, float distortion) {
      vec2 shifted = 2.0 * (uv - 0.5);
      float r2 = dot(shifted, shifted);
      shifted *= (0.88 + distortion * r2);
      return shifted * 0.5 + 0.5;
    }

    void main() {
      // Apply barrel distortion
      vec2 distortedUv = barrelDistortion(vUv, uDistortion);

      // Chromatic aberration — offset R and B channels slightly
      float ca = uChromaticAberration * (1.0 + uDistortion * 0.5);
      vec2 dir = normalize(vUv - 0.5) * ca;

      float r = texture2D(tDiffuse, barrelDistortion(vUv + dir, uDistortion)).r;
      float g = texture2D(tDiffuse, distortedUv).g;
      float b = texture2D(tDiffuse, barrelDistortion(vUv - dir, uDistortion)).b;

      vec3 color = vec3(r, g, b);

      // Mask out edge smearing caused by out-of-bounds UV sampling
      float maskX = step(0.0, distortedUv.x) * step(distortedUv.x, 1.0);
      float maskY = step(0.0, distortedUv.y) * step(distortedUv.y, 1.0);
      float mask = maskX * maskY;

      // Outside the rendered area, show the background color
      color = mix(uBgColor, color, mask);

      // Vignette effect (wider and softer, dynamically darker for dark mode)
      vec2 shifted = 2.0 * (vUv - 0.5);
      float dist = length(shifted);

      float vignetteDarkness = mix(0.3, uVignetteDarkness, uIsDark);
      float vignette = smoothstep(
        1.6, // Start fading further out
        0.5, // fully visible in the center
        dist * vignetteDarkness
      );

      // Subtle scan-line overlay on the whole scene
      float globalScan = sin(vUv.y * 800.0) * 0.015 + 1.0;

      // Only apply vignette and scanlines to the "screen" areas, not the background wall.
      // We can detect the wall by checking if the color is exactly our uBgColor.
      float isWall = step(length(color - uBgColor), 0.01);

      color = mix(color * vignette * globalScan, color, isWall);

      // Ambient glow from screens
      float glow = smoothstep(0.6, 0.0, dist) * uGlowIntensity;
      vec3 lightGlow = vec3(0.5, 0.6, 0.8) * 0.3;
      vec3 darkGlow = vec3(0.02, 0.06, 0.12) * 1.0;

      // In light mode, mask the glow from the wall. In dark mode, let it bleed (original implementation feel).
      float glowMask = mix(1.0 - isWall, 1.0, uIsDark);
      color += mix(lightGlow, darkGlow, uIsDark) * glow * glowMask;

      // Slight film grain
      float grain = fract(sin(dot(vUv + fract(uTime), vec2(12.9898, 78.233))) * 43758.5453);
      color += (grain - 0.5) * 0.02;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
};

interface DistortionPassProps {
    distortionRef?: React.MutableRefObject<{
        setDistortion: (value: number) => void;
        setGlow: (value: number) => void;
        uniforms: Record<string, { value: number }>;
    } | null>;
    isDark?: boolean;
}

export default function DistortionPass({ distortionRef, isDark = false }: DistortionPassProps) {
    const { gl, scene, camera, size } = useThree();
    const composerRef = useRef<EffectComposer | null>(null);
    const shaderPassRef = useRef<ShaderPass | null>(null);

    const { composer, shaderPass } = useMemo(() => {
        const renderTarget = new THREE.WebGLRenderTarget(
            size.width * Math.min(window.devicePixelRatio, 2),
            size.height * Math.min(window.devicePixelRatio, 2),
            {
                minFilter: THREE.LinearFilter,
                magFilter: THREE.LinearFilter,
                format: THREE.RGBAFormat,
            }
        );

        const comp = new EffectComposer(gl, renderTarget);
        const renderPass = new RenderPass(scene, camera);
        const distortionPass = new ShaderPass(DistortionShader);
        const outputPass = new OutputPass();

        comp.addPass(renderPass);
        comp.addPass(distortionPass);
        comp.addPass(outputPass);

        return { composer: comp, shaderPass: distortionPass };
    }, [gl, scene, camera, size]);

    // Store refs in effects to avoid modifying during render
    useEffect(() => {
        composerRef.current = composer;
        shaderPassRef.current = shaderPass;
    }, [composer, shaderPass]);

    // Handle theme updates
    useEffect(() => {
        if (shaderPassRef.current) {
            shaderPassRef.current.uniforms.uIsDark.value = isDark ? 1.0 : 0.0;
            const bgHex = isDark ? "#050508" : "#f7f7f9";
            shaderPassRef.current.uniforms.uBgColor.value.set(bgHex);
        }
    }, [isDark]);

    // Expose control interface for GSAP
    useEffect(() => {
        if (distortionRef) {
            distortionRef.current = {
                setDistortion: (value: number) => {
                    if (shaderPassRef.current) {
                        shaderPassRef.current.uniforms.uDistortion.value = value;
                    }
                },
                setGlow: (value: number) => {
                    if (shaderPassRef.current) {
                        shaderPassRef.current.uniforms.uGlowIntensity.value = value;
                    }
                },
                uniforms: shaderPassRef.current?.uniforms as Record<
                    string,
                    { value: number }
                >,
            };
        }
    }, [distortionRef, shaderPass]);

    // Handle resize
    useEffect(() => {
        const dpr = Math.min(window.devicePixelRatio, 2);
        composerRef.current?.setSize(size.width * dpr, size.height * dpr);
    }, [size]);

    useFrame((state) => {
        if (shaderPassRef.current) {
            shaderPassRef.current.uniforms.uTime.value = state.clock.elapsedTime;
        }
        composerRef.current?.render();
    }, 1);

    return null;
}

"use client";

import { useEffect, useRef, useCallback } from "react";
import gsap from "gsap";
import type { GridPanelRef } from "./ReplayGrid";

interface TimelineConfig {
    getPanels: () => GridPanelRef[];
    distortionControl: {
        setDistortion: (value: number) => void;
        setGlow: (value: number) => void;
        uniforms: Record<string, { value: number }>;
    } | null;
    onComplete?: () => void;
}

export default function usePreloaderTimeline() {
    const timelineRef = useRef<gsap.core.Timeline | null>(null);
    const configRef = useRef<TimelineConfig | null>(null);

    const buildTimeline = useCallback((config: TimelineConfig) => {
        configRef.current = config;
        const { getPanels, distortionControl, onComplete } = config;

        if (!distortionControl) return;

        // Kill any existing timeline
        if (timelineRef.current) {
            timelineRef.current.kill();
        }

        const panels = getPanels();
        if (panels.length === 0) return;

        const tl = gsap.timeline({
            onComplete: () => {
                onComplete?.();
            },
        });

        // Sort panels by distance from center for staggered reveal
        const centerCol = 2;
        const centerRow = 1;
        const sortedPanels = [...panels].sort((a, b) => {
            const distA = Math.abs(a.col - centerCol) + Math.abs(a.row - centerRow);
            const distB = Math.abs(b.col - centerCol) + Math.abs(b.row - centerRow);
            return distA - distB;
        });

        const nonLogoPanels = sortedPanels.filter((p) => !p.isLogo);
        const logoPanel = sortedPanels.find((p) => p.isLogo);

        // ============================================
        // PHASE 1: Boot-up — staggered panel reveal
        // ============================================

        // Set initial state
        panels.forEach((panel) => {
            panel.mesh.scale.set(0.85, 0.85, 1);
            panel.material.uniforms.uOpacity.value = 0;
            if (!panel.isLogo) {
                panel.material.uniforms.uBrightness.value = 0;
            }
        });

        // Distortion starts flat
        const distortionProxy = { value: 0, glow: 0 };

        // Logo appears first, subtly
        if (logoPanel) {
            tl.to(
                logoPanel.material.uniforms.uOpacity,
                {
                    value: 1,
                    duration: 0.8,
                    ease: "power2.out",
                },
                0.2
            );
            tl.to(
                logoPanel.mesh.scale,
                {
                    x: 1,
                    y: 1,
                    duration: 0.8,
                    ease: "back.out(1.4)",
                },
                0.2
            );
        }

        // Screens boot up from center outward
        nonLogoPanels.forEach((panel, i) => {
            const delay = 0.4 + i * 0.08;

            // Opacity in
            tl.to(
                panel.material.uniforms.uOpacity,
                {
                    value: 1,
                    duration: 0.5,
                    ease: "power2.out",
                },
                delay
            );

            // Scale in with slight bounce
            tl.to(
                panel.mesh.scale,
                {
                    x: 1,
                    y: 1,
                    duration: 0.6,
                    ease: "back.out(1.2)",
                },
                delay
            );

            // Brightness ramp up (CRT warming up)
            tl.to(
                panel.material.uniforms.uBrightness,
                {
                    value: 0.4 + Math.random() * 0.6,
                    duration: 0.8,
                    ease: "power1.in",
                },
                delay + 0.2
            );
        });

        // ============================================
        // PHASE 2: Distortion ramp — screens curve
        // ============================================
        tl.to(
            distortionProxy,
            {
                value: 0.35,
                duration: 1.8,
                ease: "power2.inOut",
                onUpdate: () => {
                    distortionControl.setDistortion(distortionProxy.value);
                },
            },
            0.6
        );

        // Ambient glow ramp
        tl.to(
            distortionProxy,
            {
                glow: 0.8,
                duration: 1.5,
                ease: "power2.out",
                onUpdate: () => {
                    distortionControl.setGlow(distortionProxy.glow);
                },
            },
            1.0
        );

        // ============================================
        // PHASE 3: Hold — screens visible with effects
        // ============================================
        // (Natural pause — no animation needed, shaders do the work)

        // Brightness pulsing for some screens
        nonLogoPanels.forEach((panel, i) => {
            if (i % 3 === 0) {
                tl.to(
                    panel.material.uniforms.uBrightness,
                    {
                        value: 0.7 + Math.random() * 0.3,
                        duration: 0.6,
                        ease: "sine.inOut",
                        yoyo: true,
                        repeat: 1,
                    },
                    2.5 + i * 0.05
                );
            }
        });

        // ============================================
        // PHASE 4: Fade out — non-center panels disappear
        // ============================================
        const fadeStart = 3.5;

        // Reverse distance sort (outer panels fade first)
        const reverseSorted = [...nonLogoPanels].reverse();

        reverseSorted.forEach((panel, i) => {
            const delay = fadeStart + i * 0.06;

            // Opacity out
            tl.to(
                panel.material.uniforms.uOpacity,
                {
                    value: 0,
                    duration: 0.6,
                    ease: "power2.in",
                },
                delay
            );

            // Scale down slightly
            tl.to(
                panel.mesh.scale,
                {
                    x: 0.9,
                    y: 0.9,
                    duration: 0.6,
                    ease: "power2.in",
                },
                delay
            );

            // Brightness dims
            tl.to(
                panel.material.uniforms.uBrightness,
                {
                    value: 0,
                    duration: 0.4,
                    ease: "power2.in",
                },
                delay
            );
        });

        // Distortion eases back to flat
        tl.to(
            distortionProxy,
            {
                value: 0.05,
                duration: 2.0,
                ease: "power3.inOut",
                onUpdate: () => {
                    distortionControl.setDistortion(distortionProxy.value);
                },
            },
            fadeStart
        );

        // ============================================
        // PHASE 5: Logo reveal — center scales up, glows
        // ============================================
        if (logoPanel) {
            tl.to(
                logoPanel.mesh.scale,
                {
                    x: 1.3,
                    y: 1.3,
                    duration: 1.2,
                    ease: "power2.out",
                },
                fadeStart + 1.0
            );

            // Glow pulse
            tl.to(
                distortionProxy,
                {
                    glow: 1.5,
                    duration: 0.8,
                    ease: "power2.out",
                    onUpdate: () => {
                        distortionControl.setGlow(distortionProxy.glow);
                    },
                },
                fadeStart + 1.2
            );
            tl.to(
                distortionProxy,
                {
                    glow: 0.3,
                    duration: 1.0,
                    ease: "power2.inOut",
                    onUpdate: () => {
                        distortionControl.setGlow(distortionProxy.glow);
                    },
                },
                fadeStart + 2.0
            );
        }

        timelineRef.current = tl;
        return tl;
    }, []);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (timelineRef.current) {
                timelineRef.current.kill();
            }
        };
    }, []);

    return { buildTimeline, timeline: timelineRef };
}

"use client";

import { useRef, useMemo, useEffect } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

// CRT screen shader — scanlines, noise, color tint
const vertexShader = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = /* glsl */ `
  uniform float uTime;
  uniform float uOpacity;
  uniform vec3 uColor;
  uniform float uIsLogo;
  uniform sampler2D uTexture;
  uniform float uHasTexture;
  uniform float uBrightness;
  uniform vec3 uBgColor;
  uniform float uIsDark;
  varying vec2 vUv;

  // Simple pseudo-random
  float rand(vec2 co) {
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
  }

  void main() {
    if (uIsLogo > 0.5) {
      if (uHasTexture > 0.5) {
        vec4 tex = texture2D(uTexture, vUv);
        // Blend logo against the exact wall color

        vec3 lightLogo = vec3(0.12, 0.14, 0.18);
        vec3 darkLogo = vec3(1.0);
        vec3 darkWall = vec3(0.0);

        vec3 activeWall = mix(uBgColor, darkWall, uIsDark);
        vec3 activeLogo = mix(lightLogo, darkLogo, uIsDark);

        vec3 finalColor = mix(activeWall, activeLogo, tex.a);
        gl_FragColor = vec4(finalColor, uOpacity);
      } else {
        // Fallback basketball logo
        vec2 center = vUv - 0.5;
        float dist = length(center);
        float circle = smoothstep(0.32, 0.30, dist) - smoothstep(0.28, 0.26, dist);
        float fill = smoothstep(0.28, 0.26, dist);

        float lineH = smoothstep(0.012, 0.008, abs(center.y));
        float lineV = smoothstep(0.012, 0.008, abs(center.x));
        float arc1 = smoothstep(0.012, 0.008, abs(length(center - vec2(0.15, 0.0)) - 0.18));
        float arc2 = smoothstep(0.012, 0.008, abs(length(center - vec2(-0.15, 0.0)) - 0.18));

        float inner = fill * max(max(lineH, lineV), max(arc1, arc2));
        float logoMask = max(circle, inner);

        vec3 lightLogo = vec3(0.12, 0.14, 0.18);
        vec3 darkLogo = vec3(1.0);
        vec3 darkWall = vec3(0.0);

        vec3 activeWall = mix(uBgColor, darkWall, uIsDark);
        vec3 activeLogo = mix(lightLogo, darkLogo, uIsDark);

        gl_FragColor = vec4(mix(activeWall, activeLogo, logoMask), uOpacity);
      }
      return;
    }

    // --- CRT Screen Effect ---
    vec3 baseColor = uColor * uBrightness;

    if (uHasTexture > 0.5 && uIsLogo < 0.5) {
      vec4 texColor = texture2D(uTexture, vUv);
      // Mix the video color with the base tint, keeping brightness control
      baseColor = mix(baseColor, texColor.rgb * uBrightness, 0.85);
    }

    // Scanlines (horizontal)
    float scanline = sin(vUv.y * 300.0 + uTime * 3.0) * 0.06;
    float scanline2 = sin(vUv.y * 100.0 - uTime * 1.5) * 0.03;

    // Animated static noise (reduced for a cleaner look)
    float baseNoiseFactor = mix(0.08, 0.12, uIsDark);
    float noise = rand(vUv * 0.5 + fract(uTime * 0.7)) * baseNoiseFactor;

    // Rolling bar (like a desynced CRT)
    float rollPos = fract(uTime * 0.15);
    float roll = smoothstep(rollPos - 0.04, rollPos, vUv.y) 
               - smoothstep(rollPos, rollPos + 0.04, vUv.y);
    roll *= 0.15;

    // Edge darkening (per-panel vignette)
    vec2 edgeDist = abs(vUv - 0.5) * 2.0;
    float panelVignette = 1.0 - dot(edgeDist, edgeDist) * 0.3;

    // Subtle color shifting / chromatic feel
    float rShift = baseColor.r + noise * 0.6 + scanline;
    float gShift = baseColor.g + noise * 0.4 + scanline2;
    float bShift = baseColor.b + noise * 0.5 + roll;

    vec3 finalColor = vec3(rShift, gShift, bShift) * panelVignette;

    // Phosphor dot grid overlay
    float dotGrid = sin(vUv.x * 600.0) * sin(vUv.y * 600.0);
    dotGrid = dotGrid * 0.03 + 1.0;
    finalColor *= dotGrid;

    // Screen edge glow (interpolated for mode)
    float edgeGlow = smoothstep(0.48, 0.5, max(abs(vUv.x - 0.5), abs(vUv.y - 0.5)));
    vec3 lightEdgeGlow = vec3(0.2, 0.25, 0.3);
    vec3 darkEdgeGlow = vec3(0.05, 0.12, 0.2); // Original broadcast blue
    finalColor += mix(lightEdgeGlow, darkEdgeGlow, uIsDark) * edgeGlow * 0.5;

    gl_FragColor = vec4(finalColor, uOpacity);
  }
`;

// Dark broadcast-tone palette for screens
const SCREEN_COLORS = [
  [0.08, 0.15, 0.25], // dark navy
  [0.12, 0.08, 0.18], // deep purple
  [0.06, 0.14, 0.12], // forest
  [0.18, 0.10, 0.06], // amber dark
  [0.10, 0.10, 0.16], // slate blue
  [0.14, 0.06, 0.10], // wine
  [0.05, 0.12, 0.20], // broadcast blue
  [0.10, 0.14, 0.08], // camo green
  [0.16, 0.08, 0.12], // maroon
  [0.08, 0.08, 0.18], // midnight
  [0.12, 0.12, 0.06], // olive
  [0.06, 0.10, 0.18], // steel blue
  [0.14, 0.10, 0.14], // dusty purple
  [0.10, 0.06, 0.06], // dark red
];

interface ScreenPanelProps {
  position: [number, number, number];
  size: [number, number];
  isLogo?: boolean;
  colorIndex?: number;
  timeOffset?: number;
  videoSrc?: string;
  imageSrc?: string;
  bgColor?: string;
  isDark?: boolean;
}

export default function ScreenPanel({
  position,
  size,
  isLogo = false,
  colorIndex = 0,
  timeOffset = 0,
  videoSrc,
  imageSrc,
  bgColor = "#f7f7f9",
  isDark = false,
}: ScreenPanelProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const materialRef = useRef<THREE.ShaderMaterial>(null);

  const color = SCREEN_COLORS[colorIndex % SCREEN_COLORS.length];

  const uniforms = useMemo(
    () => {
      // Create a specific Color instance for the background so ThreeJS handles the exact color space conversion
      const initialBg = new THREE.Color(bgColor);
      return {
        uTime: { value: 0 },
        uOpacity: { value: 0 },
        uColor: { value: new THREE.Vector3(color[0], color[1], color[2]) },
        uIsLogo: { value: isLogo ? 1.0 : 0.0 },
        uTexture: { value: new THREE.Texture() },
        uHasTexture: { value: 0.0 },
        uBrightness: { value: 1.0 },
        uBgColor: { value: initialBg },
        uIsDark: { value: isDark ? 1.0 : 0.0 },
      };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  // Update uniforms dynamically when theme changes
  useEffect(() => {
    if (materialRef.current) {
      materialRef.current.uniforms.uBgColor.value.set(bgColor);
      materialRef.current.uniforms.uIsDark.value = isDark ? 1.0 : 0.0;
    }
  }, [bgColor, isDark]);

  // Load textures manually to avoid hook conditional rendering
  useEffect(() => {
    if (!materialRef.current) return;

    if (videoSrc && !isLogo) {
      const video = document.createElement("video");
      video.crossOrigin = "Anonymous";
      video.muted = true;
      video.loop = true;
      video.playsInline = true;
      video.src = videoSrc;
      video.play().catch(() => { });

      const texture = new THREE.VideoTexture(video);
      texture.colorSpace = THREE.SRGBColorSpace;

      materialRef.current.uniforms.uTexture.value = texture;
      materialRef.current.uniforms.uHasTexture.value = 1.0;
    } else if (imageSrc && isLogo) {
      const loader = new THREE.TextureLoader();
      loader.setCrossOrigin("anonymous");
      loader.load(imageSrc, (texture) => {
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        texture.generateMipmaps = true;
        if (materialRef.current) {
          materialRef.current.uniforms.uTexture.value = texture;
          materialRef.current.uniforms.uHasTexture.value = 1.0;
        }
      });
    }
  }, [videoSrc, imageSrc, isLogo]);

  useFrame((state) => {
    if (materialRef.current) {
      materialRef.current.uniforms.uTime.value =
        state.clock.elapsedTime + timeOffset;
    }
  });

  return (
    <mesh ref={meshRef} position={position}>
      <planeGeometry args={[size[0], size[1]]} />
      <shaderMaterial
        ref={materialRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={uniforms}
        transparent
      />
    </mesh>
  );
}

