        }

        // Initial dimension set
        setDimensions({ width: initialWidth, height: window.innerHeight });

        const handleResize = () => {
            // We do NOT update isBlockedDevice here to allow resizing
            setDimensions({ width: window.innerWidth, height: window.innerHeight });
