"use client";

import { useEffect, useRef } from "react";
import * as THREE from "three";
import normalizeWheel from "normalize-wheel";
import Gallery from "./Gallery";

export default function GalleryScene() {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        if (!canvasRef.current) return;

        // --- SETUP ---
        const canvas = canvasRef.current;
        const scene = new THREE.Scene();

        const camera = new THREE.PerspectiveCamera(
            50,
            window.innerWidth / window.innerHeight,
            0.1,
            200
        );
        camera.position.z = 5;
        scene.add(camera);
        const renderer = new THREE.WebGLRenderer({
            canvas: canvas,
            alpha: true,
            antialias: true,
        });

        const dimensions = {
            width: window.innerWidth,
            height: window.innerHeight,
            pixelRatio: Math.min(2, window.devicePixelRatio),
        };

        renderer.setSize(dimensions.width, dimensions.height);
        renderer.setPixelRatio(dimensions.pixelRatio);

        const clock = new THREE.Clock();

        // --- GALLERY ---
        const gallery = new Gallery({
            scene,
            cameraZ: camera.position.z,
        });

        let lastDirection = 1;

        // --- EVENTS ---
        const handleResize = () => {
            dimensions.width = window.innerWidth;
            dimensions.height = window.innerHeight;
            dimensions.pixelRatio = Math.min(2, window.devicePixelRatio);

            camera.aspect = dimensions.width / dimensions.height;
            camera.updateProjectionMatrix();

            // Recalculate fov logic from original Canvas.ts if needed, 
            // but standard aspect update is usually sufficient unless matching exact vertical framing

            renderer.setSize(dimensions.width, dimensions.height);
            renderer.setPixelRatio(dimensions.pixelRatio);
        };

        const handleWheel = (event: WheelEvent) => {
            event.preventDefault();
            const normalizedWheel = normalizeWheel(event);
            const delta = event.deltaY;
            let value = Math.sign(event.deltaY);

            if (delta === 0) {
                value = lastDirection;
            } else {
                lastDirection = value;
            }

            // Calculate sizes.height equivalent
            const fov = camera.fov * (Math.PI / 180);
            const height = camera.position.z * Math.tan(fov / 2) * 2;

            gallery.updateScroll(
                (normalizedWheel.pixelY * height) / window.innerHeight,
                lastDirection
            );
        };

        window.addEventListener("resize", handleResize);
        window.addEventListener("wheel", handleWheel, { passive: false });

        // --- LOOP ---
        let frameId: number;
        const animate = () => {
            const time = clock.getElapsedTime();

            gallery.render(time);
            renderer.render(scene, camera);

            frameId = requestAnimationFrame(animate);
        };

        animate();

        // --- CLEANUP ---
        return () => {
            window.removeEventListener("resize", handleResize);
            window.removeEventListener("wheel", handleWheel);
            cancelAnimationFrame(frameId);

            // Dispose logic
            renderer.dispose();
            // Basic traverse dispose
            scene.traverse((object) => {
                if (object instanceof THREE.Mesh) {
                    object.geometry.dispose();
                    if (object.material.dispose) object.material.dispose();
                }
            });
        };
    }, []);

    return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full" />;
}

import * as THREE from "three";
import gsap from "gsap";
import { vertexShader, fragmentShader, centerVertexShader, centerFragmentShader } from "./shaders";

interface Props {
  scene: THREE.Scene;
  cameraZ: number;
}

interface ImageInfo {
  width: number;
  height: number;
  aspectRatio: number;
  uvs: {
    xStart: number;
    xEnd: number;
    yStart: number;
    yEnd: number;
  };
}

export default class Gallery {
  scene: THREE.Scene;
  instancedMaterial: THREE.ShaderMaterial | null = null;
  material: THREE.ShaderMaterial | null = null;
  mesh: THREE.Mesh | null = null;
  imageInfos: ImageInfo[] = [];
  atlasTexture: THREE.Texture | null = null;
  scrollY: {
    speedTarget: number;
    speedCurrent: number;
    target: number;
    current: number;
    direction: number;
  };
  cameraZ: number;
  isScrolling: boolean = false;
  textureIndex: number = 0;

  constructor({ scene, cameraZ }: Props) {
    this.scene = scene;
    this.scrollY = {
      speedTarget: 0,
      speedCurrent: 0,
      target: 0,
      current: 0,
      direction: 1,
    };
    this.cameraZ = cameraZ;

    this.loadTextureAtlas().then(() => {
      this.createInstancedMesh();
      this.createCenteredMesh();
    });
  }

  async loadTextureAtlas() {
    // Define your image paths - using the paths from the experiment structure
    const basePath = "https://experiments.raztronaut.space/experiments/rabbithole-chat-preloader/frames";
    const imagePaths = [
      `${basePath}/1.jpg`,
      `${basePath}/2.jpg`,
      `${basePath}/3.jpg`,
      `${basePath}/4.jpg`,
      `${basePath}/5.jpg`,
      `${basePath}/6.jpg`,
      `${basePath}/7.jpg`,
      `${basePath}/8.jpg`,
      `${basePath}/9.jpg`,
      `${basePath}/10.jpg`,
      `${basePath}/11.jpg`,
      `${basePath}/12.jpg`,
      `${basePath}/13.jpg`,
      `${basePath}/14.jpg`,
      `${basePath}/15.jpg`,
      `${basePath}/16.jpg`,
      `${basePath}/17.jpg`,
      `${basePath}/18.jpg`,
      `${basePath}/19.jpg`,
      `${basePath}/20.jpg`,
    ];

    // Load all images first to get their dimensions
    const version = Date.now();
    const imagePromises = imagePaths.map((path) => {
      return new Promise<HTMLImageElement>((resolve) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.src = `${path}?v=${version}`;
      });
    });

    const images = await Promise.all(imagePromises);

    // Calculate atlas dimensions (for simplicity, we'll stack images vertically)
    const atlasWidth = Math.max(...images.map((img) => img.width));
    let totalHeight = 0;

    // First pass: calculate total height
    const padding = 2;
    images.forEach((img) => {
      totalHeight += img.height + padding;
    });

    // Create canvas with calculated dimensions
    const canvas = document.createElement("canvas");
    canvas.width = atlasWidth;
    canvas.height = totalHeight;
    const ctx = canvas.getContext("2d")!;

    // Second pass: draw images and calculate normalized coordinates
    let currentY = 0;
    this.imageInfos = images.map((img) => {
      const aspectRatio = img.width / img.height;

      // Draw the image with rounded corners
      // Radius ~40px to look like 1rem on these large ~1000px images
      const r = 40;
      const x = 0;
      const y = currentY;
      const w = img.width;
      const h = img.height;

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, y + h - r);
      ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
      ctx.lineTo(x + r, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
      ctx.clip();

      ctx.drawImage(img, 0, currentY);
      ctx.restore();

      // Calculate normalized coordinates
      const info = {
        width: img.width,
        height: img.height,
        aspectRatio,
        uvs: {
          xStart: 0,
          xEnd: img.width / atlasWidth,
          yStart: 1 - currentY / totalHeight,
          yEnd: 1 - (currentY + img.height) / totalHeight,
        },
      };

      currentY += img.height + padding;
      return info;
    });

    // Create texture from canvas
    this.atlasTexture = new THREE.Texture(canvas);
    this.atlasTexture.needsUpdate = true;
    // Fix for color space/encoding if needed, usually sRGBEncoding is default in newer three,
    // but we can explicitly set it if colors look off.
    this.atlasTexture.colorSpace = THREE.SRGBColorSpace;
  }

  createInstancedMesh() {
    const geometry = new THREE.BoxGeometry(1.5, 1.5, 0.075);

    const RADIUS = 6;
    const HEIGHT = 120;
    const COUNT = 600;

    //40 circles

    const TOTAL = COUNT;

    if (!this.atlasTexture) return;

    this.instancedMaterial = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      //side: THREE.DoubleSide,
      precision: "highp",
      transparent: true,
      //blending: THREE.AdditiveBlending,
      uniforms: {
        uTime: new THREE.Uniform(0),
        uAtlas: new THREE.Uniform(this.atlasTexture),
        uScrollY: new THREE.Uniform(this.scrollY),
        uZrange: new THREE.Uniform(HEIGHT),
        uMaxZ: new THREE.Uniform(HEIGHT * 0.5),
        uSpeedY: new THREE.Uniform(0),
        uDirection: new THREE.Uniform(this.scrollY.direction),
      },
    });

    const instancedMesh = new THREE.InstancedMesh(
      geometry,
      this.instancedMaterial,
      TOTAL
    );

    // Custom buffers for per-instance attributes
    const aAngles = new Float32Array(TOTAL);
    const aHeights = new Float32Array(TOTAL);
    const aRadiuses = new Float32Array(TOTAL);
    const aAspectRatios = new Float32Array(TOTAL);
    const aSpeeds = new Float32Array(TOTAL);
    const aImagesRes = new Float32Array(TOTAL * 2);
    const aTextureCoords = new Float32Array(TOTAL * 4);

    const CIRCLE_COUNT = HEIGHT / 3; // Number of circles in the cylinder
    const CIRCLE_HEIGHT = HEIGHT / CIRCLE_COUNT;

    const speeds = new Float32Array(CIRCLE_COUNT);

    for (let j = 0; j < CIRCLE_COUNT; j++) {
      speeds[j] = Math.random() * 0.2 + 0.8;
    }

    for (let i = 0; i < COUNT; i++) {
      const angle = (i / COUNT) * Math.PI * 2;
      const imageIndex = Math.floor(Math.random() * this.imageInfos.length); // Randomly select an image index

      aTextureCoords[i * 4 + 0] = this.imageInfos[imageIndex].uvs.xStart;
      aTextureCoords[i * 4 + 1] = this.imageInfos[imageIndex].uvs.xEnd;
      aTextureCoords[i * 4 + 2] = this.imageInfos[imageIndex].uvs.yStart;
      aTextureCoords[i * 4 + 3] = this.imageInfos[imageIndex].uvs.yEnd;

      aImagesRes[i * 2 + 0] = this.imageInfos[imageIndex].width;
      aImagesRes[i * 2 + 1] = this.imageInfos[imageIndex].height;

      aAngles[i] = angle;
      aHeights[i] = (i % CIRCLE_COUNT) * CIRCLE_HEIGHT - HEIGHT / 2;
      aRadiuses[i] = RADIUS;

      aAspectRatios[i] = this.imageInfos[imageIndex].aspectRatio;
      aSpeeds[i] = speeds[i % CIRCLE_COUNT];
    }

    // Add custom attributes to geometry

    instancedMesh.geometry.setAttribute(
      "aAngle",
      new THREE.InstancedBufferAttribute(aAngles, 1)
    );

    instancedMesh.geometry.setAttribute(
      "aHeight",
      new THREE.InstancedBufferAttribute(aHeights, 1)
    );

    instancedMesh.geometry.setAttribute(
      "aRadius",
      new THREE.InstancedBufferAttribute(aRadiuses, 1)
    );
    instancedMesh.geometry.setAttribute(
      "aAspectRatio",
      new THREE.InstancedBufferAttribute(aAspectRatios, 1)
    );
    instancedMesh.geometry.setAttribute(
      "aSpeed",
      new THREE.InstancedBufferAttribute(aSpeeds, 1)
    );

    instancedMesh.geometry.setAttribute(
      "aTextureCoords",
      new THREE.InstancedBufferAttribute(aTextureCoords, 4)
    );

    instancedMesh.geometry.setAttribute(
      "aImageRes",
      new THREE.InstancedBufferAttribute(aImagesRes, 2)
    );

    this.scene.add(instancedMesh);
  }

  updateScroll(scrollY: number, direction: number) {
    this.scrollY.direction = direction;

    this.scrollY.speedTarget += scrollY;

    this.scrollY.target += scrollY;
  }

  createCenteredMesh() {
    if (!this.atlasTexture || this.imageInfos.length === 0) return;

    const geometry = new THREE.PlaneGeometry(1.7, 2.3);
    this.material = new THREE.ShaderMaterial({
      vertexShader: centerVertexShader,
      fragmentShader: centerFragmentShader,
      uniforms: {
        uAtlas: new THREE.Uniform(this.atlasTexture),
        uTextureCoords: new THREE.Uniform(
          new THREE.Vector4(
            this.imageInfos[this.textureIndex].uvs.xStart,
            this.imageInfos[this.textureIndex].uvs.xEnd,
            this.imageInfos[this.textureIndex].uvs.yStart,
            this.imageInfos[this.textureIndex].uvs.yEnd
          )
        ),
      },
      transparent: true,
    });
    this.mesh = new THREE.Mesh(geometry, this.material);
    this.scene.add(this.mesh);
  }

  render(time: number) {
    if (this.instancedMaterial && this.material && this.imageInfos.length > 0) {
      this.instancedMaterial.uniforms.uTime.value = time;
      this.scrollY.target += 0.005 * this.scrollY.direction;
      this.scrollY.speedTarget += 0.005 * this.scrollY.direction;

      this.textureIndex = Math.abs(
        Math.floor(this.scrollY.speedTarget % (this.imageInfos.length))
      );
      // Safety check for index
      if (this.textureIndex >= this.imageInfos.length) this.textureIndex = 0;
      if (Number.isNaN(this.textureIndex)) this.textureIndex = 0;

      this.material.uniforms.uTextureCoords.value.set(
        this.imageInfos[this.textureIndex].uvs.xStart,
        this.imageInfos[this.textureIndex].uvs.xEnd,
        this.imageInfos[this.textureIndex].uvs.yStart,
        this.imageInfos[this.textureIndex].uvs.yEnd
      );

      this.isScrolling = false;

      //this.speed *= 0.9

      this.scrollY.current = gsap.utils.interpolate(
        this.scrollY.current,
        this.scrollY.target,
        0.1
      );

      this.scrollY.speedCurrent = gsap.utils.interpolate(
        this.scrollY.speedCurrent,
        this.scrollY.speedTarget,
        0.1
      );

      this.instancedMaterial.uniforms.uScrollY.value = this.scrollY.current;

      this.instancedMaterial.uniforms.uSpeedY.value = this.scrollY.speedCurrent;
      this.instancedMaterial.uniforms.uDirection.value = this.scrollY.direction;
    }
  }
}

export const vertexShader = `
#define PI 3.14159265359

attribute float aAngle;
attribute float aHeight;
attribute float aRadius;
attribute float aAspectRatio;
attribute float aSpeed;
attribute vec4 aTextureCoords;
attribute vec2 aImageRes;


varying vec4 vTextureCoords;
varying vec2 vUv;
varying float vImageIndex;
varying float vAspectRatio;

uniform float uMaxZ;
uniform float uZrange;
uniform float uTime;
uniform float uScrollY;
uniform float uSpeedY;
uniform float uDirection;


vec4 getQuaternionFromAxisAngle(vec3 axis, float angle)
{
    float halfAngle = angle * 0.5;
    return vec4(axis.xyz * sin(halfAngle), cos(halfAngle));
}

vec4 multiplyQuaternions(vec4 q1, vec4 q2) {
    return vec4(
        q1.w * q2.xyz + q2.w * q1.xyz + cross(q1.xyz, q2.xyz),
        q1.w * q2.w - dot(q1.xyz, q2.xyz)
    );
}

void main() {
    vec3 scaledPosition = position;

    scaledPosition.y/=aAspectRatio;

    float zPos = aHeight + uScrollY;
    float zRange = uZrange;
    float minZ = (uMaxZ - uZrange); // Min z position
    // // Wrap around the z position
    zPos = mod(zPos - minZ, zRange) + minZ;



    float theta = aAngle - uSpeedY*1.0*aSpeed;

    vec3 instancePosition = vec3(cos(theta) * aRadius, zPos, sin(theta) * aRadius);

    // Compute angle from instance position
    float angle = atan(instancePosition.x, instancePosition.z);

    // Apply a quaternion rotation around the Y axis of angle - PI/2
    vec4 rotation = getQuaternionFromAxisAngle(vec3(0.0, 1.0, 0.0), angle);

    //apply the queternion rotation to the instance position



    vec3 finalPosition = scaledPosition +
        2.0 * cross(rotation.xyz, cross(rotation.xyz, scaledPosition) + rotation.w * scaledPosition);;

    // Apply instance translation
    vec4 modelPosition = modelMatrix * vec4(instancePosition + finalPosition, 1.0);

    vec4 viewPosition = viewMatrix * modelPosition;
    gl_Position = projectionMatrix * viewPosition;

    vUv=uv;
    vTextureCoords = aTextureCoords;
    vAspectRatio = aAspectRatio;
}`;

export const fragmentShader = `
varying vec2 vUv;
uniform sampler2D uAtlas;
varying vec4 vTextureCoords;

void main()
{

    // Get UV coordinates for this image from the uniform array
    float xStart = vTextureCoords.x;
    float xEnd = vTextureCoords.y;
    float yStart = vTextureCoords.z;
    float yEnd = vTextureCoords.w;

    // Transform the default UV coordinates to sample from the correct part of the atlas
    vec2 atlasUV = vec2(
        mix(xStart, xEnd, vUv.x),
        mix(yStart, yEnd, 1.-vUv.y)
    );

    // Sample the texture
    vec4 color = texture2D(uAtlas, atlasUV);

    // if alpha != 1 then just pass a black texture (avoid bleeding effect)


    gl_FragColor = color;

}
`;

export const centerVertexShader = `
varying vec2 vUv;

void main() {


    vec4 modelPosition = modelMatrix * vec4(position, 1.0);
    vec4 viewPosition = viewMatrix * modelPosition;
    gl_Position = projectionMatrix * viewPosition;

    vUv=uv;
}
`;

export const centerFragmentShader = `
varying vec2 vUv;
uniform sampler2D uAtlas;
uniform vec4 uTextureCoords;

void main()
{

    float xStart = uTextureCoords.x;
    float xEnd = uTextureCoords.y;
    float yStart = uTextureCoords.z;
    float yEnd = uTextureCoords.w;

    // Transform the default UV coordinates to sample from the correct part of the atlas
    vec2 atlasUV = vec2(
        mix(xStart, xEnd, vUv.x),
        mix(yStart, yEnd, 1.-vUv.y)
    );

    // Sample the texture
    vec4 color = texture2D(uAtlas, atlasUV);

    color.a = smoothstep(0.01, 0.1, color.a) * color.a;
    if (color.a < 0.01) discard;

    gl_FragColor = color;
}
`;

