"use client";

import { useEffect, useRef, RefObject, useCallback } from "react";
import { vertexShader, fragmentShader } from "./shaders";

declare global {
    interface Window {
        THREE: typeof import("three") | undefined;
    }
}

// Using generic types since THREE is loaded dynamically from CDN
interface SceneState {
    camera: object | null;
    scene: object | null;
    renderer: { dispose: () => void } | null;
    uniforms: { time: { value: number }; resolution: { value: { x: number; y: number } } } | null;
    animationId: number | null;
    onWindowResize: (() => void) | null;
}

const THREE_CDN_URL = "https://cdnjs.cloudflare.com/ajax/libs/three.js/89/three.min.js";

/**
 * Custom hook for managing a Three.js shader scene.
 * Handles dynamic loading, initialization, animation, and complete cleanup.
 */
export function useThreeShader(containerRef: RefObject<HTMLDivElement | null>) {
    const sceneRef = useRef<SceneState>({
        camera: null,
        scene: null,
        renderer: null,
        uniforms: null,
        animationId: null,
        onWindowResize: null,
    });

    const cleanup = useCallback(() => {
        const state = sceneRef.current;

        if (state.animationId !== null) {
            cancelAnimationFrame(state.animationId);
        }

        if (state.onWindowResize) {
            window.removeEventListener("resize", state.onWindowResize);
        }

        if (state.renderer) {
            state.renderer.dispose();
        }

        sceneRef.current = {
            camera: null,
            scene: null,
            renderer: null,
            uniforms: null,
            animationId: null,
            onWindowResize: null,
        };
    }, []);

    const initThreeJS = useCallback(() => {
        if (!containerRef.current || !window.THREE) return;

        // Cast to any since CDN version (r89) has different API than @types/three
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const THREE = window.THREE as any;
        const container = containerRef.current;

        // Clear any existing content
        container.innerHTML = "";

        // Initialize camera
        const camera = new THREE.Camera();
        camera.position.z = 1;

        // Initialize scene
        const scene = new THREE.Scene();

        // Create geometry
        const geometry = new THREE.PlaneBufferGeometry(2, 2);

        // Define uniforms
        const uniforms = {
            time: { value: 1.0 },
            resolution: { value: new THREE.Vector2() },
        };

        // Create material
        const material = new THREE.ShaderMaterial({
            uniforms,
            vertexShader,
            fragmentShader,
        });

        // Create mesh and add to scene
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        // Initialize renderer
        const renderer = new THREE.WebGLRenderer();
        renderer.setPixelRatio(window.devicePixelRatio);
        container.appendChild(renderer.domElement);

        // Handle resize
        const onWindowResize = () => {
            const rect = container.getBoundingClientRect();
            renderer.setSize(rect.width, rect.height);
            uniforms.resolution.value.x = renderer.domElement.width;
            uniforms.resolution.value.y = renderer.domElement.height;
        };

        onWindowResize();
        window.addEventListener("resize", onWindowResize, false);

        // Store references
        sceneRef.current = {
            camera,
            scene,
            renderer,
            uniforms,
            animationId: null,
            onWindowResize,
        };

        // Animation loop
        const animate = () => {
            sceneRef.current.animationId = requestAnimationFrame(animate);
            uniforms.time.value += 0.05;
            renderer.render(scene, camera);
        };

        animate();
    }, [containerRef]);

    useEffect(() => {
        const script = document.createElement("script");
        script.src = THREE_CDN_URL;

        script.onload = () => {
            if (containerRef.current && window.THREE) {
                initThreeJS();
            }
        };

        document.head.appendChild(script);

        return () => {
            cleanup();
            if (script.parentNode) {
                document.head.removeChild(script);
            }
        };
    }, [containerRef, initThreeJS, cleanup]);
}

/**
 * Shader code for the mosaic radial wave effect
 */

export const vertexShader = `
  void main() {
    gl_Position = vec4(position, 1.0);
  }
`;

export const fragmentShader = `
  #define TWO_PI 6.2831853072
  #define PI 3.14159265359

  precision highp float;
  uniform vec2 resolution;
  uniform float time;

  float random(in float x) {
    return fract(sin(x) * 1e4);
  }

  float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
  }

  varying vec2 vUv;

  void main(void) {
    vec2 uv = (gl_FragCoord.xy * 2.0 - resolution.xy) / min(resolution.x, resolution.y);

    vec2 fMosaicScal = vec2(8.0, 2.0);
    vec2 vScreenSize = vec2(256, 256);
    uv.x = floor(uv.x * vScreenSize.x / fMosaicScal.x) / (vScreenSize.x / fMosaicScal.x);
    uv.y = floor(uv.y * vScreenSize.y / fMosaicScal.y) / (vScreenSize.y / fMosaicScal.y);

    float t = time * 0.06 + random(uv.x) * 0.4;
    float lineWidth = 0.0008;

    vec3 color = vec3(0.0);
    for (int j = 0; j < 3; j++) {
      for (int i = 0; i < 5; i++) {
        color[j] += lineWidth * float(i * i) / abs(fract(t - 0.01 * float(j) + float(i) * 0.01) * 1.0 - length(uv));
      }
    }

    gl_FragColor = vec4(color[2], color[1], color[0], 1.0);
  }
`;

