interface SplitFlapCellProps {
    char: string;
    className?: string;
    onFlip?: () => void;
    refreshKey?: number;
}

export function SplitFlapCell({ char: targetCharProp = " ", className, onFlip, refreshKey }: SplitFlapCellProps) {
    const sanitizedTarget = useMemo(() => sanitizeChar(targetCharProp), [targetCharProp]);
    const [currentChar, setCurrentChar] = useState(" ");
    const [isScrambling, setIsScrambling] = useState(false);
    const [prevRefreshKey, setPrevRefreshKey] = useState(refreshKey);

    // Synchronize state with props during render (React recommended pattern)
    if (refreshKey !== prevRefreshKey) {
        setPrevRefreshKey(refreshKey);
        setIsScrambling(true);
        setCurrentChar(" ");
    }

    const isFlipping = currentChar !== sanitizedTarget;

    // Reset scrambling during render if we reached the target
    if (!isFlipping && isScrambling) {
        setIsScrambling(false);
    }

    useEffect(() => {
        if (!isFlipping) return;

        const timer = setTimeout(() => {
            const next = getNextChar(currentChar);
            setCurrentChar(next);

            if (onFlip) {
                if (isScrambling || Math.random() > 0.5) {
                    onFlip();
                }
            }
        }, 40);

        return () => clearTimeout(timer);
    }, [currentChar, isFlipping, onFlip, isScrambling, sanitizedTarget]);

    return (
        <div
            className={cn("relative bg-[#1a1a1a] rounded-[2px] overflow-hidden perspective-1000 select-none", className)}
            style={{
                width: 'var(--flap-w, 28px)',
                height: 'var(--flap-h, 44px)'
            }}
        >
            {/* Static Background (Target/Incoming Character) */}
            <div className="absolute inset-0 flex flex-col">
                <div className="h-1/2 w-full bg-[#1a1a1a] border-b border-black/50 flex items-end justify-center overflow-hidden">
                    <span
                        className="font-mono font-bold text-white translate-y-1/2 leading-none"
                        style={{ fontSize: 'var(--flap-font, 24px)' }}
                    >
                        {currentChar}
                    </span>
                </div>
                <div className="h-1/2 w-full bg-[#1a1a1a] flex items-start justify-center overflow-hidden">
                    <span
                        className="font-mono font-bold text-white -translate-y-1/2 leading-none"
                        style={{ fontSize: 'var(--flap-font, 24px)' }}
                    >
                        {currentChar}
                    </span>
                </div>
            </div>

            <AnimatePresence mode="popLayout">
                {isFlipping && (
                    <motion.div
                        key={currentChar}
                        initial={{ rotateX: 0 }}
                        animate={{ rotateX: -180 }}
                        exit={{ display: "none" }}
                        transition={{ duration: 0.1, ease: "linear" }}
                        style={{ transformOrigin: "bottom", zIndex: 10 }}
                        className="absolute top-0 left-0 w-full h-1/2 bg-[#1a1a1a] border-b border-black/50 flex items-end justify-center overflow-hidden backface-hidden"
                    >
                        <span
                            className="font-mono font-bold text-white translate-y-1/2 leading-none"
                            style={{ fontSize: 'var(--flap-font, 24px)' }}
                        >
                            {getPreviousChar(currentChar)}
                        </span>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Decorative center line */}
            <div className="absolute top-[calc(50%-0.5px)] md:top-[calc(50%-1px)] left-0 w-full h-[1px] md:h-[2px] bg-black/80 z-20 shadow-sm" />
        </div>
    );
}

import { CHAR_SET, NUMERIC_SET, TIME_SET, ALPHANUMERIC_SET } from './constants';

export function sanitizeChar(char: string, charSet: string = CHAR_SET): string {
    const sanitized = char.toUpperCase();
    return charSet.includes(sanitized) ? sanitized : " ";
}

export function getSafeIndex(char: string, charSet: string = CHAR_SET): number {
    const index = charSet.indexOf(char);
    return index === -1 ? 0 : index;
}

export function getNextChar(currentChar: string, charSet: string = CHAR_SET): string {
    const currentIndex = getSafeIndex(currentChar, charSet);
    const nextIndex = (currentIndex + 1) % charSet.length;
    return charSet[nextIndex];
}

export function getPreviousChar(currentChar: string, charSet: string = CHAR_SET): string {
    const currentIndex = getSafeIndex(currentChar, charSet);
    const prevIndex = (currentIndex - 1 + charSet.length) % charSet.length;
    return charSet[prevIndex];
}

export function getBestCharSet(text: string): string {
    // Check if it's purely numeric (excluding spaces)
    if (/^[0-9 ]+$/.test(text)) {
        return NUMERIC_SET;
    }

    // Check if it's a time-like string (numbers, colon, space)
    if (/^[0-9: ]+$/.test(text)) {
        return TIME_SET;
    }

    // Default to alphanumeric
    return ALPHANUMERIC_SET;
}

export const NUMERIC_SET = " 0123456789";
export const TIME_SET = " 0123456789:";
export const ALPHANUMERIC_SET = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:-.>";
export const CHAR_SET = ALPHANUMERIC_SET;

"use client";

import React, { useState, useRef, useCallback } from 'react';
import { SplitFlapCell } from './SplitFlapCell';

interface SplitFlapRowProps {
    text: string;
    length: number;
    className?: string;
    onFlip?: () => void;
    interactive?: boolean;
}

export function SplitFlapRow({ text, length, className, onFlip, interactive = false }: SplitFlapRowProps) {
    const [refreshKey, setRefreshKey] = useState(0);
    const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    const handleMouseEnter = useCallback(() => {
        if (!interactive) return;

        // Clear any existing timeout just in case
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);

        hoverTimeoutRef.current = setTimeout(() => {
            setRefreshKey(prev => prev + 1);
        }, 500); // Trigger after 0.5s of hover
    }, [interactive]);

    const handleMouseLeave = useCallback(() => {
        if (hoverTimeoutRef.current) {
            clearTimeout(hoverTimeoutRef.current);
            hoverTimeoutRef.current = null;
        }
    }, []);

    // Pad the text with spaces to match the target length
    const paddedText = text.padEnd(length, " ").slice(0, length);
    const characters = paddedText.split("");

    return (
        <div
            className={`flex ${className} ${interactive ? 'cursor-pointer' : ''}`}
            style={{ gap: 'var(--flap-gap, 2px)' }}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
        >
            {characters.map((char, index) => (
                <SplitFlapCell
                    key={index}
                    char={char}
                    onFlip={onFlip}
                    refreshKey={refreshKey}
                />
            ))}
        </div>
    );
}

