export interface TransitTrip {
    id: string;
    trainNumber: string;
    destination: string;
    arrivalTime: string;
    status: 'ON TIME' | 'DELAYED' | 'BOARDING' | 'DEPARTED';
    gate: string;
}

const CALTRAIN_MOCK: TransitTrip[] = [
    { id: 'c1', trainNumber: '305', destination: 'SAN JOSE', arrivalTime: '18:15', status: 'ON TIME', gate: '1' },
    { id: 'c2', trainNumber: '307', destination: 'TAMIEN', arrivalTime: '18:45', status: 'DELAYED', gate: '2' },
    { id: 'c3', trainNumber: '401', destination: 'SAN JOSE', arrivalTime: '19:05', status: 'BOARDING', gate: '1' },
    { id: 'c4', trainNumber: '403', destination: 'TAMIEN', arrivalTime: '19:35', status: 'ON TIME', gate: '3' },
    { id: 'c5', trainNumber: '102', destination: 'SAN FRANCISCO', arrivalTime: '18:22', status: 'DEPARTED', gate: '4' },
];

const TTC_MOCK: TransitTrip[] = [
    { id: 't1', trainNumber: 'L1', destination: 'FINCH', arrivalTime: '22:18', status: 'ON TIME', gate: 'S' },
    { id: 't2', trainNumber: '504', destination: 'BROADVIEW', arrivalTime: '22:20', status: 'BOARDING', gate: 'W' },
    { id: 't3', trainNumber: 'L1', destination: 'VAUGHAN', arrivalTime: '22:22', status: 'ON TIME', gate: 'N' },
    { id: 't4', trainNumber: '510', destination: 'UNION', arrivalTime: '22:25', status: 'DELAYED', gate: 'E' },
    { id: 't5', trainNumber: 'L2', destination: 'KIPLING', arrivalTime: '22:28', status: 'ON TIME', gate: 'W' },
];

export function useTransitData(agency: string = 'caltrain') {
    const [data, setData] = useState<TransitTrip[]>([]);
    const [loading, setLoading] = useState(true);
    const [prevAgency, setPrevAgency] = useState(agency);

    if (agency !== prevAgency) {
        setPrevAgency(agency);
        setLoading(true);
    }

    useEffect(() => {
        // Simulate initial fetch with a slight delay
        const timer = setTimeout(() => {
            setData(agency === 'ttc' ? TTC_MOCK : CALTRAIN_MOCK);
            setLoading(false);
        }, 800);

        // Simulate occasional updates or status changes
        const interval = setInterval(() => {
            setData(current =>
                current.map(trip => {
                    if (Math.random() > 0.85) {
                        const statuses: TransitTrip['status'][] = ['ON TIME', 'DELAYED', 'BOARDING', 'DEPARTED'];
                        return { ...trip, status: statuses[Math.floor(Math.random() * statuses.length)] };
                    }
                    return trip;
                })
            );
        }, 12000);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }, [agency]);

    return { data, loading };
}

"use client";

import { useCallback, useRef, useEffect } from "react";

export function useFlapSound() {
    const audioContextRef = useRef<AudioContext | null>(null);
    const masterCompressorRef = useRef<DynamicsCompressorNode | null>(null);
    const isMuted = useRef(false);

    // Concurrency tracking
    const lastTriggerTime = useRef<number>(0);
    const concurrentCount = useRef<number>(0);
    const MAX_CONCURRENT = 12; // Max sounds starting in a 50ms window
    const CONCURRENCY_WINDOW = 0.05; // 50ms

    // Cached noise buffers
    const preClickBufferRef = useRef<AudioBuffer | null>(null);
    const snapBufferRef = useRef<AudioBuffer | null>(null);
    const resonanceBufferRef = useRef<AudioBuffer | null>(null);

    useEffect(() => {
        return () => {
            if (audioContextRef.current) {
                audioContextRef.current.close();
            }
        };
    }, []);

    const createNoiseBuffer = (ctx: AudioContext, duration: number) => {
        const buffer = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
        return buffer;
    };

    const ensureContext = useCallback(() => {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext ||
                (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();

            // Initialize Master Compressor to prevent clipping
            const compressor = audioContextRef.current.createDynamicsCompressor();
            compressor.threshold.setValueAtTime(-24, audioContextRef.current.currentTime);
            compressor.knee.setValueAtTime(30, audioContextRef.current.currentTime);
            compressor.ratio.setValueAtTime(12, audioContextRef.current.currentTime);
            compressor.attack.setValueAtTime(0.003, audioContextRef.current.currentTime);
            compressor.release.setValueAtTime(0.25, audioContextRef.current.currentTime);
            compressor.connect(audioContextRef.current.destination);
            masterCompressorRef.current = compressor;
        }
        const ctx = audioContextRef.current!;
        if (ctx.state === "suspended") {
            ctx.resume();
        }

        // Pre-generate buffers if they don't exist
        if (!preClickBufferRef.current) {
            preClickBufferRef.current = createNoiseBuffer(ctx, 0.02);
            snapBufferRef.current = createNoiseBuffer(ctx, 0.04);
            resonanceBufferRef.current = createNoiseBuffer(ctx, 0.15);
        }

        return ctx;
    }, []);

    const playClick = useCallback(() => {
        if (isMuted.current) return;

        try {
            const ctx = ensureContext();
            const now = ctx.currentTime;

            // --- Concurrency Limit Logic ---
            if (now - lastTriggerTime.current < CONCURRENCY_WINDOW) {
                concurrentCount.current++;
                if (concurrentCount.current > MAX_CONCURRENT) return; // Drop sound
            } else {
                concurrentCount.current = 1;
                lastTriggerTime.current = now;
            }

            // --- Dynamic Volume Scaling ---
            // If many cells are flapping, reduce individual volume slightly
            const loadFactor = Math.min(1, concurrentCount.current / MAX_CONCURRENT);
            const masterVolScale = 1 - (loadFactor * 0.4); // Scale down by up to 40%

            // --- Randomization Engine ---
            // Each "clack" should be unique to avoid machine-gun effect
            const pitchJitter = 1 + (Math.random() - 0.5) * 0.15;
            const volJitter = 0.8 + Math.random() * 0.4;
            const panValue = (Math.random() - 0.5) * 0.4; // Subtle stereo spread

            const panner = ctx.createStereoPanner();
            panner.pan.setValueAtTime(panValue, now);
            panner.connect(masterCompressorRef.current || ctx.destination);

            /**
             * Layer 0: The "Pre-Click" (Flap clearing the previous one)
             * Very subtle, slightly earlier transient
             */
            const preDelay = 0.015;
            const preClickDuration = 0.02;
            if (preClickBufferRef.current) {
                const source = ctx.createBufferSource();
                source.buffer = preClickBufferRef.current;

                const bandpass = ctx.createBiquadFilter();
                bandpass.type = "bandpass";
                bandpass.frequency.setValueAtTime(4000 * pitchJitter, now);
                bandpass.Q.setValueAtTime(10, now);

                const gain = ctx.createGain();
                gain.gain.setValueAtTime(0, now);
                gain.gain.linearRampToValueAtTime(0.02 * volJitter * masterVolScale, now + 0.002);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + preClickDuration);

                source.connect(bandpass);
                bandpass.connect(gain);
                gain.connect(panner);

                source.start(now);
                source.stop(now + preClickDuration);
            }

            /**
             * Layer 1: The "Snap" (Main Transient)
             * Sharp high-frequency click when the flap hits the stopper
             */
            const mainTime = now + preDelay;
            const snapDuration = 0.04;
            if (snapBufferRef.current) {
                const source = ctx.createBufferSource();
                source.buffer = snapBufferRef.current;

                const bandpass = ctx.createBiquadFilter();
                bandpass.type = "bandpass";
                bandpass.frequency.setValueAtTime(3200 * pitchJitter, mainTime);
                bandpass.Q.setValueAtTime(4, mainTime);

                const gain = ctx.createGain();
                gain.gain.setValueAtTime(0, mainTime);
                gain.gain.linearRampToValueAtTime(0.08 * volJitter * masterVolScale, mainTime + 0.003);
                gain.gain.exponentialRampToValueAtTime(0.0001, mainTime + snapDuration);

                source.connect(bandpass);
                bandpass.connect(gain);
                gain.connect(panner);

                source.start(mainTime);
                source.stop(mainTime + snapDuration);
            }

            /**
             * Layer 2: The "Thud" (Impact Body)
             * Low frequency component representing the mass of the flap
             */
            {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                const lp = ctx.createBiquadFilter();

                osc.type = "triangle";
                osc.frequency.setValueAtTime(160 * pitchJitter, mainTime);
                osc.frequency.exponentialRampToValueAtTime(60 * pitchJitter, mainTime + 0.06);

                lp.type = "lowpass";
                lp.frequency.setValueAtTime(800, mainTime);

                gain.gain.setValueAtTime(0, mainTime);
                gain.gain.linearRampToValueAtTime(0.06 * volJitter * masterVolScale, mainTime + 0.012);
                gain.gain.exponentialRampToValueAtTime(0.0001, mainTime + 0.1);

                osc.connect(lp);
                lp.connect(gain);
                gain.connect(panner);

                osc.start(mainTime);
                osc.stop(mainTime + 0.12);
            }

            /**
             * Layer 3: The "Resonance" (Metallic Ring)
             * Short-lived metallic vibration after impact
             */
            const resonanceDuration = 0.15;
            if (resonanceBufferRef.current) {
                const source = ctx.createBufferSource();
                source.buffer = resonanceBufferRef.current;

                const bandpass = ctx.createBiquadFilter();
                bandpass.type = "bandpass";
                bandpass.frequency.setValueAtTime(1200 * pitchJitter, mainTime + 0.01);
                bandpass.Q.setValueAtTime(15, mainTime); // High Q for metallic feel

                const gain = ctx.createGain();
                gain.gain.setValueAtTime(0, mainTime + 0.01);
                gain.gain.linearRampToValueAtTime(0.03 * volJitter * masterVolScale, mainTime + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, mainTime + resonanceDuration);

                source.connect(bandpass);
                bandpass.connect(gain);
                gain.connect(panner);

                source.start(mainTime + 0.01);
                source.stop(mainTime + resonanceDuration + 0.02);
            }

        } catch (e) {
            console.warn("Audio playback failed:", e);
        }
    }, [ensureContext]);

    const setMuted = useCallback((muted: boolean) => {
        isMuted.current = muted;
    }, []);

    return { playClick, setMuted };
}

"use client";

import React, { useState, useRef, useCallback } from 'react';
import { SplitFlapCell } from './SplitFlapCell';

interface SplitFlapRowProps {
    text: string;
    length: number;
    className?: string;
    onFlip?: () => void;
    interactive?: boolean;
}

export function SplitFlapRow({ text, length, className, onFlip, interactive = false }: SplitFlapRowProps) {
    const [refreshKey, setRefreshKey] = useState(0);
    const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    const handleMouseEnter = useCallback(() => {
        if (!interactive) return;

        // Clear any existing timeout just in case
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);

        hoverTimeoutRef.current = setTimeout(() => {
            setRefreshKey(prev => prev + 1);
        }, 500); // Trigger after 0.5s of hover
    }, [interactive]);

    const handleMouseLeave = useCallback(() => {
        if (hoverTimeoutRef.current) {
            clearTimeout(hoverTimeoutRef.current);
            hoverTimeoutRef.current = null;
        }
    }, []);

    // Pad the text with spaces to match the target length
    const paddedText = text.padEnd(length, " ").slice(0, length);
    const characters = paddedText.split("");

    return (
        <div
            className={`flex ${className} ${interactive ? 'cursor-pointer' : ''}`}
            style={{ gap: 'var(--flap-gap, 2px)' }}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
        >
            {characters.map((char, index) => (
                <SplitFlapCell
                    key={index}
                    char={char}
                    onFlip={onFlip}
                    refreshKey={refreshKey}
                />
            ))}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';
import { getPreviousChar, getNextChar, sanitizeChar } from './utils';

interface SplitFlapCellProps {
    char: string;
    className?: string;
    onFlip?: () => void;
    refreshKey?: number;
}

export function SplitFlapCell({ char: targetCharProp = " ", className, onFlip, refreshKey }: SplitFlapCellProps) {
    const sanitizedTarget = useMemo(() => sanitizeChar(targetCharProp), [targetCharProp]);
    const [currentChar, setCurrentChar] = useState(" ");
    const [isScrambling, setIsScrambling] = useState(false);
    const [prevRefreshKey, setPrevRefreshKey] = useState(refreshKey);

    // Synchronize state with props during render (React recommended pattern)
    if (refreshKey !== prevRefreshKey) {
        setPrevRefreshKey(refreshKey);
        setIsScrambling(true);
        setCurrentChar(" ");
    }

    const isFlipping = currentChar !== sanitizedTarget;

    // Reset scrambling during render if we reached the target
    if (!isFlipping && isScrambling) {
        setIsScrambling(false);
    }

    useEffect(() => {
        if (!isFlipping) return;

        const timer = setTimeout(() => {
            const next = getNextChar(currentChar);
            setCurrentChar(next);

            if (onFlip) {
                if (isScrambling || Math.random() > 0.5) {
                    onFlip();
                }
            }
        }, 40);

        return () => clearTimeout(timer);
    }, [currentChar, isFlipping, onFlip, isScrambling, sanitizedTarget]);

    return (
        <div
            className={cn("relative bg-[#1a1a1a] rounded-[2px] overflow-hidden perspective-1000 select-none", className)}
            style={{
                width: 'var(--flap-w, 28px)',
                height: 'var(--flap-h, 44px)'
            }}
        >
            {/* Static Background (Target/Incoming Character) */}
            <div className="absolute inset-0 flex flex-col">
                <div className="h-1/2 w-full bg-[#1a1a1a] border-b border-black/50 flex items-end justify-center overflow-hidden">
                    <span
                        className="font-mono font-bold text-white translate-y-1/2 leading-none"
                        style={{ fontSize: 'var(--flap-font, 24px)' }}
                    >
                        {currentChar}
                    </span>
                </div>
                <div className="h-1/2 w-full bg-[#1a1a1a] flex items-start justify-center overflow-hidden">
                    <span
                        className="font-mono font-bold text-white -translate-y-1/2 leading-none"
                        style={{ fontSize: 'var(--flap-font, 24px)' }}
                    >
                        {currentChar}
                    </span>
                </div>
            </div>

            <AnimatePresence mode="popLayout">
                {isFlipping && (
                    <motion.div
                        key={currentChar}
                        initial={{ rotateX: 0 }}
                        animate={{ rotateX: -180 }}
                        exit={{ display: "none" }}
                        transition={{ duration: 0.1, ease: "linear" }}
                        style={{ transformOrigin: "bottom", zIndex: 10 }}
                        className="absolute top-0 left-0 w-full h-1/2 bg-[#1a1a1a] border-b border-black/50 flex items-end justify-center overflow-hidden backface-hidden"
                    >
                        <span
                            className="font-mono font-bold text-white translate-y-1/2 leading-none"
                            style={{ fontSize: 'var(--flap-font, 24px)' }}
                        >
                            {getPreviousChar(currentChar)}
                        </span>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Decorative center line */}
            <div className="absolute top-[calc(50%-0.5px)] md:top-[calc(50%-1px)] left-0 w-full h-[1px] md:h-[2px] bg-black/80 z-20 shadow-sm" />
        </div>
    );
}

import { CHAR_SET, NUMERIC_SET, TIME_SET, ALPHANUMERIC_SET } from './constants';

export function sanitizeChar(char: string, charSet: string = CHAR_SET): string {
    const sanitized = char.toUpperCase();
    return charSet.includes(sanitized) ? sanitized : " ";
}

export function getSafeIndex(char: string, charSet: string = CHAR_SET): number {
    const index = charSet.indexOf(char);
    return index === -1 ? 0 : index;
}

export function getNextChar(currentChar: string, charSet: string = CHAR_SET): string {
    const currentIndex = getSafeIndex(currentChar, charSet);
    const nextIndex = (currentIndex + 1) % charSet.length;
    return charSet[nextIndex];
}

export function getPreviousChar(currentChar: string, charSet: string = CHAR_SET): string {
    const currentIndex = getSafeIndex(currentChar, charSet);
    const prevIndex = (currentIndex - 1 + charSet.length) % charSet.length;
    return charSet[prevIndex];
}

export function getBestCharSet(text: string): string {
    // Check if it's purely numeric (excluding spaces)
    if (/^[0-9 ]+$/.test(text)) {
        return NUMERIC_SET;
    }

    // Check if it's a time-like string (numbers, colon, space)
    if (/^[0-9: ]+$/.test(text)) {
        return TIME_SET;
    }

    // Default to alphanumeric
    return ALPHANUMERIC_SET;
}

