        damping: 30,
        stiffness: 100
    },
    IMAGE_TRANSITION: {
        type: "spring" as const,
        damping: 30,
        stiffness: 150
    },
    IMAGE_MOTION: {
        type: "spring" as const,
        damping: 25,
        stiffness: 120,
        mass: 0.5
    }
};

